54	@RestController
55	@CrossOrigin(exposedHeaders = "errors, content-type")
56	@RequestMapping("/api")
57	public class OwnerRestControllerV1 implements OwnersApi {
58	
59	    private final ClinicService clinicService;
60	
61	    private final OwnerMapper ownerMapper;
62	
63	    private final PetMapper petMapper;
64	
65	    private final VisitMapper visitMapper;
66	
67	    private final TelephoneNormalizer telephoneNormalizer;
68	
69	    private final EmailNormalizer emailNormalizer;
70	
71	    public OwnerRestControllerV1(ClinicService clinicService,
72	                                 OwnerMapper ownerMapper,
73	                                 PetMapper petMapper,
74	                                 VisitMapper visitMapper,
75	                                 TelephoneNormalizer telephoneNormalizer,
76	                                 EmailNormalizer emailNormalizer) {
77	        this.clinicService = clinicService;
78	        this.ownerMapper = ownerMapper;
79	        this.petMapper = petMapper;
80	        this.visitMapper = visitMapper;
81	        this.telephoneNormalizer = telephoneNormalizer;
82	        this.emailNormalizer = emailNormalizer;
83	    }
84	
85	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
86	    @Override
87	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
88	        Collection<Owner> owners;
89	        if (lastName != null) {
90	            owners = this.clinicService.findOwnerByLastName(lastName);
91	        } else {
92	            owners = this.clinicService.findAllOwners();
93	        }
94	        if (owners.isEmpty()) {
95	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
96	        }
97	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
98	    }
99	
100	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
101	    @Override
102	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
103	        Owner owner = this.clinicService.findOwnerById(ownerId);
104	        if (owner == null) {
105	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
106	        }
107	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
108	    }
109	
110	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
111	    @Override
112	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
113	        HttpHeaders headers = new HttpHeaders();
114	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
115	        Optional<String> e164Telephone = telephoneNormalizer.toE164(owner.getTelephone());
116	        if (e164Telephone.isEmpty()) {
117	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
118	        }
119	        String telephone = e164Telephone.get();
120	        String email = emailNormalizer.normalize(owner.getEmail());
121	        if (email != null && !emailNormalizer.isValid(email)) {
122	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
123	        }
124	        if (clinicService.existsOwnerByTelephone(telephone)) {
125	            return new ResponseEntity<>(HttpStatus.CONFLICT);
126	        }
127	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())
128	            && clinicService.existsOwnerByLastNameAndAddress(owner.getLastName(), owner.getAddress())) {
129	            return new ResponseEntity<>(HttpStatus.CONFLICT);
130	        }
131	        owner.setTelephone(telephone);
132	        owner.setEmail(email);
133	        this.clinicService.saveOwner(owner);
134	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
135	        headers.setLocation(UriComponentsBuilder.newInstance()
136	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
137	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
138	    }
139	
140	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
141	    @Override
142	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
143	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
144	        if (currentOwner == null) {
145	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
146	        }
147	        Optional<String> e164Telephone = telephoneNormalizer.toE164(ownerFieldsDto.getTelephone());
148	        if (e164Telephone.isEmpty()) {
149	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
150	        }
151	        String email = emailNormalizer.normalize(ownerFieldsDto.getEmail());
152	        if (email != null && !emailNormalizer.isValid(email)) {
153	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
154	        }
155	        currentOwner.setAddress(ownerFieldsDto.getAddress());
156	        currentOwner.setCity(ownerFieldsDto.getCity());
157	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
158	        currentOwner.setLastName(ownerFieldsDto.getLastName());
159	        currentOwner.setTelephone(e164Telephone.get());
160	        currentOwner.setEmail(email);
161	        this.clinicService.saveOwner(currentOwner);
162	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
163	    }
164	
165	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
166	    @Transactional
167	    @Override
168	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
169	        Owner owner = this.clinicService.findOwnerById(ownerId);
170	        if (owner == null) {
171	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
172	        }
173	        this.clinicService.deleteOwner(owner);
174	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
175	    }
176	
177	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
178	    @Override
179	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
180	        Owner owner = this.clinicService.findOwnerById(ownerId);
181	        if (owner == null) {
182	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
183	        }
184	        HttpHeaders headers = new HttpHeaders();
185	        Pet pet = petMapper.toPet(petFieldsDto);
186	        owner.setId(ownerId);
187	        pet.setOwner(owner);
188	        pet.getType().setName(null);
189	        this.clinicService.savePet(pet);
190	        PetDto petDto = petMapper.toPetDto(pet);
191	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
192	            .buildAndExpand(pet.getId()).toUri());
193	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
194	    }
195	
196	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
197	    @Override
198	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
199	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
200	        if (currentOwner != null) {
201	            Pet currentPet = this.clinicService.findPetById(petId);
202	            if (currentPet != null) {
203	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
204	                currentPet.setName(petFieldsDto.getName());
205	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
206	                this.clinicService.savePet(currentPet);
207	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
208	            }
209	        }
210	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
211	    }
212	
213	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
214	    @Override
215	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
216	        HttpHeaders headers = new HttpHeaders();
217	        Visit visit = visitMapper.toVisit(visitFieldsDto);
218	        Pet pet = new Pet();
219	        pet.setId(petId);
220	        visit.setPet(pet);
221	        this.clinicService.saveVisit(visit);
222	        VisitDto visitDto = visitMapper.toVisitDto(visit);
223	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
224	            .buildAndExpand(visit.getId()).toUri());
225	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
226	    }
227	
228	
229	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
230	    @Override
231	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
232	        Owner owner = this.clinicService.findOwnerById(ownerId);
233	        if (owner != null) {
234	            Pet pet = owner.getPet(petId);
235	            if (pet != null) {
236	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
237	            }
238	        }
239	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
240	    }
241	}
