27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "registration_date")
55	    private LocalDate registrationDate;
56	
57	    @Column(name = "customer_code")
58	    private String customerCode;
59	
60	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
61	    private Set<Pet> pets;
62	
63	    public String getAddress() {
64	        return this.address;
65	    }
66	
67	    public void setAddress(String address) {
68	        this.address = address;
69	    }
70	
71	    public String getCity() {
72	        return this.city;
73	    }
74	
75	    public void setCity(String city) {
76	        this.city = city;
77	    }
78	
79	    public String getTelephone() {
80	        return this.telephone;
81	    }
82	
83	    public void setTelephone(String telephone) {
84	        this.telephone = telephone;
85	    }
86	
87	    public String getEmail() {
88	        return this.email;
89	    }
90	
91	    public void setEmail(String email) {
92	        this.email = email;
93	    }
94	
95	    public LocalDate getRegistrationDate() {
96	        return this.registrationDate;
97	    }
98	
99	    public void setRegistrationDate(LocalDate registrationDate) {
100	        this.registrationDate = registrationDate;
101	    }
102	
103	    public String getCustomerCode() {
104	        return this.customerCode;
105	    }
106	
107	    public void setCustomerCode(String customerCode) {
108	        this.customerCode = customerCode;
109	    }
110	
111	    /**
112	     * Default the registration date to the server's current date when none was
113	     * supplied, so every newly persisted owner has a registration date.
114	     */
115	    @PrePersist
116	    void defaultRegistrationDate() {
117	        if (this.registrationDate == null) {
118	            this.registrationDate = LocalDate.now();
119	        }
120	    }
121	
122	    protected Set<Pet> getPetsInternal() {
123	        if (this.pets == null) {
124	            this.pets = new HashSet<>();
125	        }
126	        return this.pets;
127	    }
128	
129	    protected void setPetsInternal(Set<Pet> pets) {
130	        this.pets = pets;
131	    }
132	
133	    public List<Pet> getPets() {
134	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
135	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
136	        return Collections.unmodifiableList(sortedPets);
137	    }
138	
139	    public void setPets(List<Pet> pets) {
140	        this.pets = new HashSet<>(pets);
141	    }
142	
143	    public void addPet(Pet pet) {
144	        getPetsInternal().add(pet);
145	        pet.setOwner(this);
146	    }
147	
148	    /**
149	     * Return the Pet with the given name, or null if none found for this Owner.
150	     *
151	     * @param name to test
152	     * @return true if pet name is already in use
153	     */
154	    public Pet getPet(String name) {
155	        return getPet(name, false);
156	    }
157	
158	    /**
159	     * Return the Pet with the given name, or null if none found for this Owner.
160	     *
161	     * @param name to test
162	     * @return true if pet name is already in use
163	     */
164	    public Pet getPet(String name, boolean ignoreNew) {
165	        name = name.toLowerCase();
166	        for (Pet pet : getPetsInternal()) {
167	            if (!ignoreNew || !pet.isNew()) {
168	                String compName = pet.getName();
169	                compName = compName.toLowerCase();
170	                if (compName.equals(name)) {
171	                    return pet;
172	                }
173	            }
174	        }
175	        return null;
176	    }
177	
178	    public Pet getPet(Integer petId) {
179	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
180	    }
181	
182	    @Override
183	    public String toString() {
184	        return new ToStringCreator(this)
185	
186	            .append("id", this.getId())
187	            .append("new", this.isNew())
188	            .append("lastName", this.getLastName())
189	            .append("firstName", this.getFirstName())
190	            .append("address", this.address)
191	            .append("city", this.city)
192	            .append("telephone", this.telephone)
193	            .toString();
194	    }
195	}
