20	import java.util.regex.Pattern;
21	
22	import org.springframework.stereotype.Component;
23	
24	/**
25	 * Normalizes and validates an owner's telephone number into E.164 form.
26	 *
27	 * <p>A leading {@code '+'} and country code are kept when present; otherwise the
28	 * default country code {@link #DEFAULT_COUNTRY_CODE} is assumed and a single
29	 * leading {@code '0'} is dropped from the national digits. Spaces, dashes and
30	 * brackets are stripped. The result is only accepted when it carries between
31	 * {@link #MIN_DIGITS} and {@link #MAX_DIGITS} digits after the {@code '+'}.
32	 */
33	@Component
34	public class TelephoneNormalizer {
35	
36	    /** Country code assumed when the raw number has no explicit {@code '+'} prefix. */
37	    public static final String DEFAULT_COUNTRY_CODE = "61";
38	
39	    /** The fewest digits a valid E.164 number may have after the {@code '+'}. */
40	    public static final int MIN_DIGITS = 8;
41	
42	    /** The most digits a valid E.164 number may have after the {@code '+'}. */
43	    public static final int MAX_DIGITS = 15;
44	
45	    /** Separators that carry no numeric meaning and are stripped before parsing. */
46	    private static final Pattern SEPARATORS = Pattern.compile("[\\s()\\-]");
47	
48	    private static final Pattern DIGITS = Pattern.compile("\\d+");
49	
50	    /**
51	     * Convert a raw telephone value into its E.164 representation.
52	     *
53	     * @param telephone the raw telephone value (may be {@code null})
54	     * @return the E.164 number (e.g. {@code "+61412345678"}), or
55	     *         {@link Optional#empty()} if it cannot form a valid E.164 number
56	     */
57	    public Optional<String> toE164(String telephone) {
58	        if (telephone == null) {
59	            return Optional.empty();
60	        }
61	        String trimmed = telephone.trim();
62	        boolean explicitCountryCode = trimmed.startsWith("+");
63	        String body = explicitCountryCode ? trimmed.substring(1) : trimmed;
64	        String digits = SEPARATORS.matcher(body).replaceAll("");
65	        if (!DIGITS.matcher(digits).matches()) {
66	            return Optional.empty();
67	        }
68	        if (!explicitCountryCode) {
69	            String national = digits.startsWith("0") ? digits.substring(1) : digits;
70	            digits = DEFAULT_COUNTRY_CODE + national;
71	        }
72	        if (digits.length() < MIN_DIGITS || digits.length() > MAX_DIGITS) {
73	            return Optional.empty();
74	        }
75	        return Optional.of("+" + digits);
76	    }
77	}
