268	     * whitespace to a single space and lower-case, so that differences in case or
269	     * spacing do not defeat the duplicate-household check.
270	     */
271	    private static String normalizeIdentity(String value) {
272	        if (value == null) {
273	            return "";
274	        }
275	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
276	    }
277	
278	    @Override
279	    @Transactional(readOnly = true)
280	    public Collection<Visit> findVisitsByPetId(int petId) {
281	        return visitRepository.findByPetId(petId);
282	    }
283	
284	    @Override
285	    @Transactional(readOnly = true)
286	    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
287	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
288	    }
289	
290	    private <T> T findEntityById(Supplier<T> supplier) {
291	        try {
292	            return supplier.get();
293	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
294	            // Just ignore not found exceptions for Jdbc/Jpa realization
295	            return null;
296	        }
297	    }
